const root='/Users/ilyagulya/Projects/My/bend',dir='/private/tmp/bend-e01-e13-jbsb4I',hash=p=>createHash('sha256').update(readFileSync(p)).digest('hex'),json=p=>JSON.parse(readFileSync(p,'utf8'));
