const request=resolve(root,'checkpoints/local2039g32c-full/throughput/control-js.request.json'),authority=json(request),restored=json(root+'/evals/receipts/producer2039g34_restored_r12.json');
for(const [p,h]of Object.entries(authority.pins))if(realpathSync(p)!==p||hash(p)!==h)throw Error('Authority drift '+p);
