import {readFileSync} from 'node:fs';
import {createHash} from 'node:crypto';

const HOOK = '__allFusionCoverageObserve';
const BOUNDARY = 'emitter_steps_v1.emitter_body_cps_provider_8_js_scalar_program';
const HOT_PRODUCER = '../bend2/selfhost/checker_arena.metadata_write';
const PREFIX = '../bend2/selfhost/backend_ir.';
const LIMIT = {codes: 50000, nodes: 4000000, list: 1000000, sites: 100000, suffix: 8192, samples: 128, edges: 1000000};
let report = {schemaVersion: 1, status: 'not-instrumented', boundaryCalls: 0};
const sha = text => createHash('sha256').update(text).digest('hex');
const tag = value => typeof value?.$ === 'string' ? value.$.startsWith(PREFIX) ? value.$.slice(PREFIX.length) : value.$ : '<invalid>';
const inc = (object, key, n = 1) => { object[key] = (object[key] || 0) + n; };
const escapeRE = value => value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

// Every list is the actual emitted Nil/Con representation, not an array model.
function list(value, cap = LIMIT.list) {
  const result = [];
  while (value?.$ === 'Con') {
    if (result.length === cap) throw new Error('list-bound');
    result.push(value.head); value = value.tail;
  }
  if (value?.$ !== 'Nil') throw new Error('unexpected-list-tag:' + String(value?.$));
  return result;
}
function atoms(op) {
  switch (tag(op)) {
    case 'Copy': case 'Project': case 'HasTag': return [op.value];
    case 'Direct': case 'TailDirect': case 'PrimitiveCall': return list(op.args).map(a => a.value);
    case 'Apply': case 'TailApply': return [op.fn, op.arg.value];
    case 'Closure': return list(op.captures).map(a => a.value);
    case 'Construct': return list(op.fields).map(a => a.value);
    case 'LoadSymbol': return [];
    default: throw new Error('unknown-operation:' + tag(op));
  }
}
function children(block) {
  switch (tag(block)) {
    case 'Let': return [block.next];
    case 'Branch': return [block.no, block.yes];
    case 'Region': return [block.next, block.body];
    case 'Return': case 'TailDirect': case 'TailApply': case 'LeaveRegion': case 'Failure': return [];
    default: throw new Error('unknown-block:' + tag(block));
  }
}
function walk(root, fn, budget, cap = LIMIT.nodes) {
  const stack = [root]; let n = 0;
  while (stack.length) {
    if (++n > cap || ++budget.nodes > LIMIT.nodes) throw new Error(n > cap ? 'suffix-bound' : 'node-bound');
    const b = stack.pop(); fn(b); stack.push(...children(b));
  }
  return n;
}
function readAtoms(block) {
  if (tag(block) === 'Let') return atoms(block.op);
  if (tag(block) === 'Return') return [block.value];
  if (tag(block) === 'Branch') return [block.condition];
  if (tag(block) === 'TailDirect' || tag(block) === 'TailApply') return atoms(block);
  return [];
}
function uses(root, id, budget) {
  const result = {projects: [], tags: 0, tagTests: [], whole: [], branches: 0, regions: 0, leaves: [], freeLeaves: [], captures: 0, affineCaptures: 0, opaqueApply: 0, identity: 0, nodes: 0, freeLocals: 0, freeSlots: 0};
  const bound = new Set([id]), read = new Set(), slots = new Set(), labels = new Set();
  result.nodes = walk(root, b => {
    const bt = tag(b), op = bt === 'Let' ? b.op : b, ot = tag(op);
    if (bt === 'Let') bound.add(b.id);
    if (bt === 'Branch') result.branches++;
    if (bt === 'Region') {result.regions++; labels.add(b.label);}
    if (bt === 'LeaveRegion') result.leaves.push(b.label);
    if (ot === 'Apply' || ot === 'TailApply') result.opaqueApply++;
    for (const a of readAtoms(b)) {if (tag(a) === 'Local') read.add(a.id); if (tag(a) === 'Capture') slots.add(a.slot);}
    const aa = readAtoms(b);
    const positions = aa.flatMap((a, index) => tag(a) === 'Local' && a.id === id ? [index] : []);
    if (!positions.length) return;
    if (ot === 'Project') {result.projects.push({constructor: op.constructor, field: op.field, key: op.key}); return;}
    if (ot === 'HasTag') {result.tags++; result.tagTests.push({constructor: op.constructor, tag: op.tag}); return;}
    if (ot === 'Closure') {
      result.captures += positions.length;
      const cs = list(op.captures);
      for (const i of positions) if (tag(cs[i].use) === 'Affine') result.affineCaptures++;
    }
    if (ot === 'PrimitiveCall' && tag(op.primitive) === 'PrimSameValue') result.identity++;
    result.whole.push({kind: ot, code: op.code ?? null, positions});
  }, budget, LIMIT.suffix);
  result.freeLeaves = [...new Set(result.leaves.filter(x => !labels.has(x)))];
  result.freeLocals = [...read].filter(x => !bound.has(x)).length;
  result.freeSlots = slots.size;
  return result;
}
function graphFacts(summaries) {
  // Iterative Kosaraju: no recursion through either JS or target closures.
  const seen = new Set(), order = [], reverse = new Map();
  for (const id of summaries.keys()) reverse.set(id, []);
  for (const [id, s] of summaries) for (const to of s.edges) if (reverse.has(to)) reverse.get(to).push(id);
  for (const start of summaries.keys()) {
    if (seen.has(start)) continue;
    seen.add(start); const stack = [[start, 0, [...summaries.get(start).edges].filter(x => summaries.has(x))]];
    while (stack.length) {
      const frame = stack[stack.length - 1];
      if (frame[1] === frame[2].length) {order.push(frame[0]); stack.pop(); continue;}
      const next = frame[2][frame[1]++];
      if (!seen.has(next)) {seen.add(next); stack.push([next, 0, [...summaries.get(next).edges].filter(x => summaries.has(x))]);}
    }
  }
  const component = new Map(), sizes = [];
  for (let i = order.length - 1; i >= 0; i--) {
    const start = order[i]; if (component.has(start)) continue;
    const c = sizes.length, stack = [start]; component.set(start, c); let size = 0;
    while (stack.length) {const id = stack.pop(); size++; for (const from of reverse.get(id)) if (!component.has(from)) {component.set(from, c); stack.push(from);}}
    sizes.push(size);
  }
  // order is postorder; acyclic callees precede callers. Any cyclic dependency
  // is conservatively excluded from the first bounded specialization scope.
  for (const id of order) {
    const s = summaries.get(id); s.scc = component.get(id); s.sccSize = sizes[s.scc];
    s.recursive = s.sccSize > 1 || s.edges.has(id);
    s.acyclic = !s.recursive && [...s.edges].every(to => summaries.get(to)?.acyclic === true);
  }
  return {components: sizes.length, recursiveComponents: sizes.filter(x => x > 1).length, recursiveCodes: [...summaries.values()].filter(s => s.recursive).length, order};
}
function census(program, mapping, manifestInfo) {
  const budget = {nodes: 0};
  const out = {phase: globalThis.__allExperimentPhase ?? 'unknown', status: 'running', boundary: BOUNDARY,
    limits: LIMIT, codes: 0, declarations: {}, blocks: {}, operations: {}, directSites: 0,
    reasons: {}, reasonExamples: {}, dispositions: {}, coverageClasses: {}, samples: [], smallestCandidate: null, knownHotSites: [],
    sourceCounts: {}, sourceCountsOmitted: 0, localScalarizer: {sites: 0, eligible: 0, reasons: {}},
    producerShapes: {}, graph: null, generatorReports: manifestInfo,
    dynamicCalls: {status: 'new-counters-not-collected', reason: 'New sites are discovered during full-root emit, after check/expand. Existing G33 metadata_write witness remains valid evidence of relevance, not a new R12 count.'}};
  report.result = out; // Partial scalar-only facts survive a diagnostic budget stop.
  const codes = list(program.codes, LIMIT.codes), declarations = list(program.declarations), names = new Map(), summaries = new Map(), sites = [];
  const ctorNames = new Map(list(program.constructors).map(x => [x.id, x.key]));
  const exported = new Set();
  if (tag(program.ending) === 'Library') {
    for (const ex of list(program.ending.exports)) if (ex.entry?.$ === 'Some') exported.add(ex.entry.value.code);
  } else if (tag(program.ending) !== 'Executable') throw new Error('unexpected-ending');
  for (const d of declarations) {
    inc(out.declarations, tag(d));
    if (tag(d) === 'FunctionDeclaration') {if (!names.has(d.code)) names.set(d.code, []); names.get(d.code).push(d.key);}
    if (tag(d) === 'LazyDeclaration') {
      const id = 'lazy:' + d.key;
      names.set(id, [d.key]);
      codes.push({$: PREFIX + 'Code', id, captures: {$: 'Nil'}, parameters: {$: 'Nil'}, body: d.body});
      if (codes.length > LIMIT.codes) throw new Error('code-bound');
    }
  }
  const identity = id => ({code: id, entry: typeof id === 'string' ? 'lazy' : exported.has(id) ? 'exported' : 'private-code', names: names.get(id) ?? [], frozenFunctions: (names.get(id) ?? []).flatMap(key => mapping[key] ? [{key, ...mapping[key]}] : [])});
  let edges = 0;
  for (const c of codes) {
    if (tag(c) !== 'Code' || summaries.has(c.id)) throw new Error('invalid-or-duplicate-code');
    summaries.set(c.id, {id: c.id, code: c, edges: new Set(), tail: new Set(), returns: [], unknownReturns: 0, nodes: 0, branches: 0, regions: 0, labels: new Set(), leaves: new Set(), opaque: 0, failures: 0, captures: list(c.captures).length, parameters: list(c.parameters), nonterminalConstruction: 0});
  }
  out.codes = codes.length;
  for (const c of codes) {
    const s = summaries.get(c.id);
    const stack = [{b: c.body, env: new Map()}];
    while (stack.length) {
      if (++budget.nodes > LIMIT.nodes) throw new Error('node-bound');
      const {b, env} = stack.pop(), bt = tag(b); s.nodes++; inc(out.blocks, bt);
      if (bt === 'Let') {
        const op = b.op, ot = tag(op); inc(out.operations, ot);
        if (ot === 'Direct') {
          s.edges.add(op.code); if (++edges > LIMIT.edges) throw new Error('edge-bound');
          out.directSites++;
          if (sites.length === LIMIT.sites) throw new Error('site-bound');
          sites.push({owner: c.id, id: b.id, producer: op.code, next: b.next, args: list(op.args).length});
        }
        if (ot === 'Apply') s.opaque++;
        if (ot === 'Construct') {
          const fs = list(op.fields);
          const shape = {constructor: op.constructor, tag: op.tag, fields: fs.map(f => ({key: f.key, identity: f.identity, use: tag(f.use), atom: tag(f.value)})), terminal: tag(b.next) === 'Return' && tag(b.next.value) === 'Local' && b.next.value.id === b.id};
          env.set(b.id, shape);
          out.localScalarizer.sites++;
          if (fs.some(f => ['Symbol', 'FloatBits'].includes(tag(f.value)))) inc(out.localScalarizer.reasons, 'evaluating-field');
          else {
            try {
              const u = uses(b.next, b.id, budget);
              if (!u.whole.length && !u.tags && u.projects.every(p => fs.some(f => f.key === p.key))) out.localScalarizer.eligible++;
              else inc(out.localScalarizer.reasons, 'record-observed-or-missing-field');
            } catch (e) {if (e.message !== 'suffix-bound') throw e; inc(out.localScalarizer.reasons, 'suffix-bound');}
          }
        } else if (ot === 'Copy' && tag(op.value) === 'Local' && env.has(op.value.id)) env.set(b.id, env.get(op.value.id));
        else env.delete(b.id);
        stack.push({b: b.next, env});
      } else if (bt === 'Branch') {s.branches++; stack.push({b: b.no, env: new Map(env)}, {b: b.yes, env: new Map(env)});}
      else if (bt === 'Region') {s.regions++; s.labels.add(b.label); stack.push({b: b.next, env: new Map(env)}, {b: b.body, env});}
      else if (bt === 'Return') {
        const value = tag(b.value) === 'Local' ? env.get(b.value.id) : null;
        if (value) {s.returns.push(value); if (!value.terminal) s.nonterminalConstruction++;} else s.unknownReturns++;
      } else if (bt === 'TailDirect') {s.tail.add(b.code); s.edges.add(b.code); if (++edges > LIMIT.edges) throw new Error('edge-bound');}
      else if (bt === 'TailApply') {s.opaque++; s.unknownReturns++;}
      else if (bt === 'LeaveRegion') s.leaves.add(b.label);
      else if (bt === 'Failure') s.failures++;
      else throw new Error('unknown-block:' + bt);
    }
  }
  const graph = graphFacts(summaries); out.graph = {components: graph.components, recursiveComponents: graph.recursiveComponents, recursiveCodes: graph.recursiveCodes};
  for (const id of graph.order) {
    const s = summaries.get(id);
    s.freeLeaves = [...s.leaves].filter(x => !s.labels.has(x));
    s.returnSummary = new Map(); s.exitCount = s.returns.length; s.returnUnknown = s.unknownReturns > 0 || !s.acyclic;
