  const byPhase = offset => Object.fromEntries(PHASES.map((p, i) => [p, state.hits[offset + i]]).filter(([, n]) => n));
  const rows = state.sites.map(site => {
    const phases = byPhase(site.id * PHASES.length);
    const count = Object.values(phases).reduce((a, b) => a + b, 0);
    return { ...site, count, phases };
  });
