    const key = row.category + ':' + row.kind;
    if (!aggregate.has(key)) aggregate.set(key, { category: row.category, kind: row.kind, matches: 0,
      declaredFieldExposure: 0, unconditionalProjectionStatements: 0, referencedProjectionStatements: 0,
      lexicallyUnreferencedProjectionStatements: 0, phases: {} });
    const out = aggregate.get(key);
    out.matches += row.count;
    out.declaredFieldExposure += row.count * row.declaredFields.length;
    out.unconditionalProjectionStatements += row.count * row.projectedFields.length;
    out.referencedProjectionStatements += row.count * row.referencedProjectionFields.length;
    out.lexicallyUnreferencedProjectionStatements += row.count * (row.projectedFields.length - row.referencedProjectionFields.length);
