    const offset = (category * state.readStride + kind) * PHASES.length;
    const phases = Object.fromEntries(PHASES.map((p, i) => [p, state.reads[offset + i]]).filter(([, n]) => n));
    const count = Object.values(phases).reduce((a, b) => a + b, 0);
    if (count) retrievals.push({ category: category ? 'pattern' : 'node',
      kind: state.kindTags[kind]?.slice(PREFIX.length) || 'UNKNOWN', count, phases });
  }
  const rank = (a, b) => b.count - a.count || a.id - b.id;
  const candidate = matched.filter(r => r.kind === 'TermAll' && r.referencedProjectionFields.length === 1 &&
    r.referencedProjectionFields[0] === 'body_id' && r.staticContexts.some(name => CANDIDATES.some(c => name.endsWith('_' + c))));
