    imageSha256: state.imageSha256, coverage: state.coverage,
    status: rows.some(r => r.count) ? 'OBSERVED_NOT_QUALIFIED' : 'INSTRUMENTED_NOT_EXECUTED',
    fullDescriptorRetrievals: retrievals.sort((a, b) => b.count - a.count),
    kindAccess: [...aggregate.values()].sort((a, b) => b.matches - a.matches),
    topConsumerSites: matched.filter(r => r.count).sort(rank).slice(0, 96),
